-- Preserve legacy raw text for source compatibility while materializing typed readings.
-- A reading of 0, 0.001 or 0.01 is an unmeasured sentinel, never an average sample.
ALTER TABLE mrtb
    ADD COLUMN recosi_value DOUBLE AS (CASE WHEN REGEXP_REPLACE(TRIM(`recosi`), '[^0-9.+-]', '') REGEXP '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)$' AND CAST(REGEXP_REPLACE(TRIM(`recosi`), '[^0-9.+-]', '') AS DOUBLE) NOT IN (0, 0.001, 0.01) THEN CAST(REGEXP_REPLACE(TRIM(`recosi`), '[^0-9.+-]', '') AS DOUBLE) ELSE NULL END) PERSISTENT,
    ADD COLUMN recosi_unmeasured TINYINT(1) AS (CASE WHEN REGEXP_REPLACE(TRIM(`recosi`), '[^0-9.+-]', '') REGEXP '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)$' AND CAST(REGEXP_REPLACE(TRIM(`recosi`), '[^0-9.+-]', '') AS DOUBLE) IN (0, 0.001, 0.01) THEN 1 ELSE 0 END) PERSISTENT,
    ADD COLUMN coldtp_value DOUBLE AS (CASE WHEN REGEXP_REPLACE(TRIM(`coldtp`), '[^0-9.+-]', '') REGEXP '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)$' AND CAST(REGEXP_REPLACE(TRIM(`coldtp`), '[^0-9.+-]', '') AS DOUBLE) NOT IN (0, 0.001, 0.01) THEN CAST(REGEXP_REPLACE(TRIM(`coldtp`), '[^0-9.+-]', '') AS DOUBLE) ELSE NULL END) PERSISTENT,
